"""
    This function is a good bit scrambling function.

    This algorithm was created for sdbm (a public-domain
     reimplementation of ndbm) database library.
    """
def sdbm(key: Any) -> object {
    hash = 0;
    for letter in str(key) {
        hash = (ord(letter) + (hash << 6) + (hash << 16)) - hash;
    }
    return hash;
}

"""
    Function returns the dict of positions according to the level of space or comma
    Example: {'1_,': [14], '2_,': [9], '0_ ': [3], '1_ ': [12]}
        comma of level 1: position 14
        comma of level 2: position 9
        space of level 0: position 3
        space of level 1: position 12
    """
def add_to_dict_of_levels(
    dict_levels: Any, c: Any, cur_level: Any, index: Any
) -> object {
    symbol = str(cur_level) + '_' + c;
    if (symbol not in dict_levels) {
        dict_levels[symbol] = [];
    }
    dict_levels[symbol].append(index);
    return dict_levels;
}

"""
    e.g.
    lst = range(13) & n = 3
    return = [[0, 3, 6, 9, 12], [1, 4, 7, 10], [2, 5, 8, 11]]
    """
def chunkify(lst: Any, n: Any) -> object {
    return [lst[i::n] for i in range(n)];
}

"""
    Convert time in days / hrs / mins etc to total seconds used)
    """
def str_2_sec(timein: Any) -> object {
    splitdays = timein.split('-');
    if (len(splitdays) == 2) {
        secs = (24 * 60 * 60 * int(splitdays[0])) + str_2_sec(splitdays[1]);
    } elif (len(splitdays) == 1) {
        splittime = timein.split(':');
        assert (len(splittime) == 3) , 'not enough bits';
        secs = (
            int(splittime[2]) + (60 * int(splittime[1])) + (60 * 60 * int(splittime[0]))
        );
    } else {
        assert False , 'time conversion error';
    }
    return secs;
}

